use verus::prelude::*;

verus! {
    /// Intersperse `delim` between the elements of `numbers`.
    ///
    /// If `numbers.len() == 0`, the result is empty.
    /// Otherwise, the result has length `2*n - 1` where `n = numbers.len()`,
    /// with the property that
    ///   - at even indices `j`, `result[j] == numbers[j/2]`, and
    ///   - at odd indices `j`,  `result[j] == delim`.
    pub fn intersperse(numbers: &Slice<i32>, delim: i32) -> Vec<i32>
      ensures numbers.len() == 0 ==> result.len() == 0
      ensures numbers.len() > 0  ==> result.len() == 2 * numbers.len() - 1
      ensures forall |j: usize| j < result.len() ==>
                if j % 2 == 0 {
                    result[j] == numbers[j / 2]
                } else {
                    result[j] == delim
                }
    {
        let n = numbers.len();
        // Case: empty input => empty output
        if n == 0 {
            let res: Vec<i32> = Vec::new();
            return res;
        }

        // Otherwise, allocate exact capacity 2*n - 1
        let mut res = Vec::with_capacity(2 * n - 1);

        // Push the first element of `numbers`
        res.push(numbers.index(0));

        // Now intersperse: for each remaining element numbers[i],
        // first push `delim`, then push the element.
        let mut i: usize = 1;
        while i < n {
            // Invariant: we've processed `i` elements from `numbers`,
            // so `res.len() == 2*i - 1`, and the prefix of `res` is
            // already correctly interspersed.
            invariant i <= n;
            invariant res.len() == 2 * i - 1;
            invariant forall |j: usize| j < res.len() ==>
                      if j % 2 == 0 {
                          res[j] == numbers[j / 2]
                      } else {
                          res[j] == delim
                      };
            decreases n - i;

            res.push(delim);
            res.push(numbers.index(i));
            i += 1;
        }

        // Final checks
        assert(res.len() == 2 * n - 1);
        assert(forall |j: usize| j < res.len() ==>
               if j % 2 == 0 {
                   res[j] == numbers[j / 2]
               } else {
                   res[j] == delim
               });

        res
    }
}